import React from "react";
import { Card } from "@mui/material";
import { theme } from "../../styles/styles";
// import paperSizes from "../../screens/pageCalculator"
import { makeStyles } from "tss-react/mui";
import { useDispatch, useSelector } from "react-redux";
import { AppDispatch, RootState } from "../../store";
import { setGrammage, setLength, setWidth } from "../../store/pageSlice";


const useStyles = makeStyles()(() => ({
    div:{
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "center",
    },
  button: {
    padding: theme.spacing.lg,
    margin: theme.spacing.md,
    borderRadius: theme.borderRadius.lg,
    backgroundColor: theme.colors.background,

    textAlign: "center",
  },
}));
const paperSizes = {
  "A2": { length: 100, width: 150 },
  "A3": { length: 200, width: 250 },
  "A4": { length: 300, width: 350 },
  "A5": { length: 400, width: 450 },
  "A6": { length: 500, width: 550 },
  "DL": { length: 500, width: 650 }
};
export const dins = {
  "DIN A": 80,
  "DIN B": 100,
  "DIN C": 90,
  "JIS B": 80,
  "US Formats": 75
};


const Formats = () =>{
    const { classes } = useStyles();
    const dispatch = useDispatch<AppDispatch>();
    const {length, width, grammage, numberOfSheets, format} = useSelector((state: RootState) => state.page)


    return(
        <>
        <div className={classes.div}>

        <button className={classes.button} onClick={() =>{
            dispatch(setLength(paperSizes["A2" as keyof typeof paperSizes].length))
            dispatch(setWidth(paperSizes["A2" as keyof typeof paperSizes].width))
            }}>A2</button>
        <button className={classes.button} onClick={() =>{
            dispatch(setLength(paperSizes["A3" as keyof typeof paperSizes].length))
            dispatch(setWidth(paperSizes["A3" as keyof typeof paperSizes].width))
            }}>A2</button>
        <button className={classes.button} onClick={() =>{
            dispatch(setLength(paperSizes["A4" as keyof typeof paperSizes].length))
            dispatch(setWidth(paperSizes["A4" as keyof typeof paperSizes].width))
            }}>A2</button>
        <button className={classes.button} onClick={() =>{
            dispatch(setLength(paperSizes["A5" as keyof typeof paperSizes].length))
            dispatch(setWidth(paperSizes["A5" as keyof typeof paperSizes].width))
            }}>A2</button>
        <button className={classes.button} onClick={() =>{
            dispatch(setLength(paperSizes["A6" as keyof typeof paperSizes].length))
            dispatch(setWidth(paperSizes["A6" as keyof typeof paperSizes].width))
            }}>A2</button>
        <button className={classes.button} onClick={() =>{
            dispatch(setLength(paperSizes["DL" as keyof typeof paperSizes].length))
            dispatch(setWidth(paperSizes["DL" as keyof typeof paperSizes].width))
            }}>A2</button>

        </div>
        <div className={classes.div}>

        <button className={classes.button} onClick={() =>{
            dispatch(setGrammage(dins["DIN A" as keyof typeof dins]))
            }}>DIN A</button>
        <button className={classes.button} onClick={() =>{
            dispatch(setGrammage(dins["DIN B" as keyof typeof dins]))
            }}>DIN B</button>
        <button className={classes.button} onClick={() =>{
            dispatch(setGrammage(dins["DIN C" as keyof typeof dins]))
            }}>DIN C</button>
       <button className={classes.button} onClick={() =>{
            dispatch(setGrammage(dins["JIS B" as keyof typeof dins]))
            }}>JIS B</button>
        </div>
        <button className={classes.button} onClick={() =>{
            dispatch(setGrammage(dins["DIN A" as keyof typeof dins]))
            }}>DIN A</button>

        </>


    )
}



export default Formats;
